#!/usr/bin/env bun
// @bun
var CINEMA_ID="0000000002";var BASE_URL="https://www.classiccinemas.com.au/api";var AEST_OFFSET_MS=10*60*60*1000;async function fetchJson(url,destPath){const resp=await fetch(url);if(!resp.ok){throw new Error(`GET ${url} failed: ${resp.status} ${resp.statusText}`)}const text=await resp.text();if(destPath){await Bun.write(destPath,text)}return JSON.parse(text)}async function readOrFetchJson(path,url){const file=Bun.file(path);if(await file.exists()){return JSON.parse(await file.text())}return fetchJson(url,path)}function seatmapTmpPath(sessionId){return`/tmp/cc-seatmap-${sessionId}.json`}function seatmapUrl(sessionId){return`${BASE_URL}/sessions/${CINEMA_ID}/${sessionId}/seating-map`}function formatTime(isoStr){const timePart=isoStr.split("T")[1]??"";const[hStr="0",mStr="0"]=timePart.split(":");let hours=Number.parseInt(hStr,10);const minutes=Number.parseInt(mStr,10);const ampm=hours>=12?"pm":"am";hours=hours%12;if(hours===0)hours=12;const mm=minutes.toString().padStart(2,"0");return`${hours}:${mm}${ampm}`}function todayAest(){const now=new Date;const local=new Date(now.getTime()+AEST_OFFSET_MS);return local.toISOString().slice(0,10)}function maybeExitWithHelp(arg,help){if(arg==="-h"||arg==="--help"){console.log(help);process.exit(0)}}function runMain(main){main().catch((err)=>{console.error(err instanceof Error?err.message:String(err));process.exit(1)})}var HELP=`classic-cinema check-availability \u2014 seat availability per session

Usage:
  bun run src/check-availability.ts --session-ids 122899,122893,122898

Options:
  --session-ids LIST   Comma-separated session ids (required)
  -h, --help           Show this help

Output: one JSON object per line on stdout. Diagnostics on stderr.
Exit: 0 ok, 1 none processed, 64 invalid usage.`;function calcAvailability(seatmap){const screen=seatmap.areas?.[0]?.name??"";let total=0;let unavail=0;for(const row of seatmap.rows??[]){for(const seat of row.seats??[]){if(seat.typeId==="gap")continue;total+=1;if(seat.sold||seat.unavailable)unavail+=1}}const available=total-unavail;const pct=total?Math.round(available/total*100):0;return{screen,available,total,pct}}function parseArgs(argv){let sessionIds=null;for(let i=0;i<argv.length;i++){const arg=argv[i];maybeExitWithHelp(arg,HELP);if(arg==="--session-ids"){sessionIds=argv[++i]??""}else if(arg.startsWith("--session-ids=")){sessionIds=arg.slice("--session-ids=".length)}else{console.error(`Unknown argument: ${arg}`);console.error(HELP);process.exit(64)}}if(sessionIds===null){console.error("Missing required --session-ids");console.error(HELP);process.exit(64)}return{sessionIds}}async function main(){const{sessionIds}=parseArgs(process.argv.slice(2));const sids=sessionIds.split(",").map((s)=>s.trim()).filter((s)=>s.length>0);if(sids.length===0){console.error("No session IDs provided");process.exit(1)}let processed=0;for(const sid of sids){const path=seatmapTmpPath(sid);let seatmap;try{const file=Bun.file(path);seatmap=await file.exists()?JSON.parse(await file.text()):await fetchJson(seatmapUrl(sid),path)}catch(err){const msg=err instanceof Error?err.message:String(err);console.error(`Failed to load seatmap for session ${sid}: ${msg}`);continue}const result=calcAvailability(seatmap);console.log(JSON.stringify({...result,sid:Number.parseInt(sid,10)}));processed+=1}if(processed===0){console.error("No seatmap files could be processed");process.exit(1)}}if(import.meta.main){runMain(main)}export{calcAvailability};
